package errcheck

import (
	"go/token"
	"sort"
)

// UncheckedError describes a single location where a returned error (or a
// type assertion result) was silently discarded.
type UncheckedError struct {
	// Pos is the position in the source file where the problem was found.
	Pos token.Position
	// Line holds the trimmed text of the source line at Pos.
	Line string
	// FuncName is the fully qualified name of the called function, if it
	// could be determined (empty otherwise).
	FuncName string
}

// Result accumulates the problems found while checking a set of packages.
type Result struct {
	UncheckedErrors []UncheckedError
}

// Append merges the problems of other into r.
func (r *Result) Append(other Result) {
	r.UncheckedErrors = append(r.UncheckedErrors, other.UncheckedErrors...)
}

// Unique returns a copy of r with its problems sorted by position and with
// exact duplicates (which arise when the same file is part of several
// package variants, e.g. a package and its test variant) removed.
func (r Result) Unique() Result {
	list := make([]UncheckedError, len(r.UncheckedErrors))
	copy(list, r.UncheckedErrors)
	sort.Slice(list, func(i, j int) bool {
		return less(list[i], list[j])
	})
	out := make([]UncheckedError, 0, len(list))
	for i, e := range list {
		if i > 0 && list[i-1] == e {
			continue
		}
		out = append(out, e)
	}
	return Result{UncheckedErrors: out}
}

func less(a, b UncheckedError) bool {
	if a.Pos.Filename != b.Pos.Filename {
		return a.Pos.Filename < b.Pos.Filename
	}
	if a.Pos.Line != b.Pos.Line {
		return a.Pos.Line < b.Pos.Line
	}
	if a.Pos.Column != b.Pos.Column {
		return a.Pos.Column < b.Pos.Column
	}
	if a.FuncName != b.FuncName {
		return a.FuncName < b.FuncName
	}
	return a.Line < b.Line
}
