package errcheck

import (
	"go/types"
)

// interfaceChain determines, for a method value selection, the chain of
// interface types that the selected method is reached through.
//
// Struct fields along the selection path (including those of embedded
// structs) are walked first. If the type that ultimately provides the method
// is not an interface, ok is false. Otherwise the returned slice starts with
// that interface type and continues with every embedded interface traversed
// until the one which explicitly declares the method.
func interfaceChain(sel *types.Selection) (chain []types.Type, ok bool) {
	fn, isFunc := sel.Obj().(*types.Func)
	if !isFunc {
		return nil, false
	}

	cur := sel.Recv()
	idx := sel.Index()
	if len(idx) == 0 {
		return nil, false
	}
	// All indexes but the last denote struct fields; the last one selects
	// the method itself.
	for _, fieldIdx := range idx[:len(idx)-1] {
		next, found := fieldTypeAt(cur, fieldIdx)
		if !found {
			return nil, false
		}
		cur = next
	}

	iface, isIface := asInterface(cur)
	if !isIface {
		return nil, false
	}

	chain = append(chain, cur)
	for !declaresMethod(iface, fn.Name()) {
		embedded, next, found := embeddedProviding(iface, fn.Name())
		if !found {
			break
		}
		chain = append(chain, embedded)
		iface = next
	}
	return chain, true
}

// fieldTypeAt returns the type of the i-th field of the struct underlying t
// (dereferencing one level of pointer if necessary).
func fieldTypeAt(t types.Type, i int) (types.Type, bool) {
	u := t.Underlying()
	if p, isPtr := u.(*types.Pointer); isPtr {
		u = p.Elem().Underlying()
	}
	st, isStruct := u.(*types.Struct)
	if !isStruct || i < 0 || i >= st.NumFields() {
		return nil, false
	}
	return st.Field(i).Type(), true
}

// asInterface returns the interface underlying t, if any.
func asInterface(t types.Type) (*types.Interface, bool) {
	if t == nil {
		return nil, false
	}
	iface, isIface := t.Underlying().(*types.Interface)
	return iface, isIface
}

// declaresMethod reports whether iface explicitly declares a method called
// name (as opposed to inheriting it from an embedded interface).
func declaresMethod(iface *types.Interface, name string) bool {
	for i := 0; i < iface.NumExplicitMethods(); i++ {
		if iface.ExplicitMethod(i).Name() == name {
			return true
		}
	}
	return false
}

// embeddedProviding finds the first embedded interface of iface whose method
// set contains a method called name.
func embeddedProviding(iface *types.Interface, name string) (types.Type, *types.Interface, bool) {
	for i := 0; i < iface.NumEmbeddeds(); i++ {
		et := iface.EmbeddedType(i)
		inner, isIface := asInterface(et)
		if !isIface {
			continue
		}
		for j := 0; j < inner.NumMethods(); j++ {
			if inner.Method(j).Name() == name {
				return et, inner, true
			}
		}
	}
	return nil, nil, false
}
