// Package errcheck implements detection of silently discarded errors in Go
// source code.
package errcheck

import (
	"fmt"
	"os"
	"regexp"
	"strings"
	"sync"

	"golang.org/x/tools/go/packages"
)

// Checker holds the configuration for a run.
type Checker struct {
	// Blank enables reporting of errors assigned to the blank identifier.
	Blank bool
	// Asserts enables reporting of type assertions whose result is not
	// checked with the two-value form.
	Asserts bool
	// WithoutTests disables loading of _test.go files.
	WithoutTests bool
	// WithoutGenerated skips files that carry a generated-code marker.
	WithoutGenerated bool
	// Verbose enables progress logging to stderr.
	Verbose bool
	// Tags are build tags passed through to the go tool.
	Tags []string
	// Mod is the module download mode (-mod) passed through to the go tool.
	Mod string
	// Ignore maps a package path (or "" for all packages) to a regular
	// expression matched against the called identifier's name.
	Ignore map[string]*regexp.Regexp

	// Symbols holds the exclude list used when a run is performed.
	Symbols []string

	exclude map[string]bool
}

func (c *Checker) logf(format string, args ...interface{}) {
	if c.Verbose {
		fmt.Fprintf(os.Stderr, format+"\n", args...)
	}
}

func (c *Checker) excludeSet() map[string]bool {
	if c.exclude != nil {
		return c.exclude
	}
	set := make(map[string]bool, len(c.Symbols))
	for _, s := range c.Symbols {
		set[s] = true
	}
	c.exclude = set
	return set
}

// LoadPackages loads (and type-checks) the packages matching the given
// patterns, honouring the build tags, module mode and test configuration.
func (c *Checker) LoadPackages(patterns ...string) ([]*packages.Package, error) {
	flags := []string{"-tags=" + strings.Join(c.Tags, ",")}
	if c.Mod != "" {
		flags = append(flags, "-mod="+c.Mod)
	}
	cfg := &packages.Config{
		Mode:       packages.LoadAllSyntax,
		Tests:      !c.WithoutTests,
		BuildFlags: flags,
	}
	return packages.Load(cfg, patterns...)
}

// CheckPackage inspects a single loaded package.
func (c *Checker) CheckPackage(pkg *packages.Package) Result {
	v := &visitor{
		pkg:     pkg,
		ignore:  c.Ignore,
		blank:   c.Blank,
		asserts: c.Asserts,
		exclude: c.excludeSet(),
		lines:   make(map[string][]string),
	}
	for _, file := range pkg.Syntax {
		if c.WithoutGenerated && isGeneratedFile(file) {
			continue
		}
		v.inspectFile(file)
	}
	return Result{UncheckedErrors: v.found}
}

// CheckPaths loads the packages matching patterns and checks all of them,
// returning the combined, de-duplicated result.
func (c *Checker) CheckPaths(patterns ...string) (Result, error) {
	pkgs, err := c.LoadPackages(patterns...)
	if err != nil {
		return Result{}, err
	}
	for _, pkg := range pkgs {
		if len(pkg.Errors) > 0 {
			return Result{}, fmt.Errorf("errors while loading package %s: %v", pkg.PkgPath, pkg.Errors)
		}
	}

	var (
		wg    sync.WaitGroup
		mu    sync.Mutex
		total Result
	)
	for _, pkg := range pkgs {
		wg.Add(1)
		go func(pkg *packages.Package) {
			defer wg.Done()
			c.logf("checking %s", pkg.PkgPath)
			r := c.CheckPackage(pkg)
			mu.Lock()
			total.Append(r)
			mu.Unlock()
		}(pkg)
	}
	wg.Wait()
	return total.Unique(), nil
}
EOF
echo ok

