package errcheck

import (
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"regexp"
	"strings"

	"golang.org/x/tools/go/packages"
)

// errorIface is the universe "error" interface.
var errorIface = types.Universe.Lookup("error").Type().Underlying().(*types.Interface)

// visitor walks the syntax trees of one package and records problems.
type visitor struct {
	pkg     *packages.Package
	ignore  map[string]*regexp.Regexp
	blank   bool
	asserts bool
	exclude map[string]bool

	lines map[string][]string
	found []UncheckedError
}

func (v *visitor) info() *types.Info { return v.pkg.TypesInfo }

func (v *visitor) inspectFile(f *ast.File) {
	ast.Inspect(f, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.ExprStmt:
			if call, ok := node.X.(*ast.CallExpr); ok {
				v.checkCallStmt(call)
			}
		case *ast.GoStmt:
			v.checkCallStmt(node.Call)
		case *ast.DeferStmt:
			v.checkCallStmt(node.Call)
		case *ast.AssignStmt:
			v.checkAssignment(node.Lhs, node.Rhs)
		case *ast.ValueSpec:
			lhs := make([]ast.Expr, len(node.Names))
			for i, name := range node.Names {
				lhs[i] = name
			}
			v.checkAssignment(lhs, node.Values)
		case *ast.TypeAssertExpr:
			v.checkAssertExpr(node)
		}
		return true
	})
}

// checkCallStmt handles a call used as a statement (plain, go or defer).
func (v *visitor) checkCallStmt(call *ast.CallExpr) {
	if v.isIgnored(call) || v.isExcluded(call) {
		return
	}
	if v.isRecover(call) || v.returnsError(call) {
		v.report(call.Lparen, call)
	}
}

// checkAssignment handles both assignment statements and var declarations.
func (v *visitor) checkAssignment(lhs, rhs []ast.Expr) {
	if len(rhs) == 1 {
		switch r := rhs[0].(type) {
		case *ast.CallExpr:
			if !v.blank || v.isIgnored(r) || v.isExcluded(r) {
				return
			}
			flags := v.errorResults(r)
			rec := v.isRecover(r)
			for i, l := range lhs {
				id, ok := l.(*ast.Ident)
				if !ok || id.Name != "_" {
					continue
				}
				if rec || (i < len(flags) && flags[i]) {
					v.report(id.NamePos, r)
				}
			}
		case *ast.TypeAssertExpr:
			if !v.asserts || r.Type == nil {
				return
			}
			if len(lhs) < 2 {
				v.report(r.Pos(), nil)
			} else if id, ok := lhs[1].(*ast.Ident); ok && v.blank && id.Name == "_" {
				v.report(id.NamePos, nil)
			}
		}
		return
	}

	for i, l := range lhs {
		id, ok := l.(*ast.Ident)
		if !ok || i >= len(rhs) {
			continue
		}
		switch r := rhs[i].(type) {
		case *ast.CallExpr:
			if !v.blank || v.isIgnored(r) || v.isExcluded(r) {
				continue
			}
			if id.Name == "_" && (v.isRecover(r) || v.returnsError(r)) {
				v.report(id.NamePos, r)
			}
		case *ast.TypeAssertExpr:
			if !v.asserts || r.Type == nil {
				continue
			}
			v.report(id.NamePos, nil)
		}
	}
}

// checkAssertExpr reports single-value type assertions wherever they occur.
func (v *visitor) checkAssertExpr(e *ast.TypeAssertExpr) {
	if !v.asserts || e.Type == nil {
		return
	}
	if tv, ok := v.info().Types[e]; ok {
		if _, isTuple := tv.Type.(*types.Tuple); isTuple {
			// comma-ok form: the result is checked
			return
		}
	}
	v.report(e.Pos(), nil)
}

// isRecover reports whether call invokes the recover builtin.
func (v *visitor) isRecover(call *ast.CallExpr) bool {
	id, ok := call.Fun.(*ast.Ident)
	if !ok {
		return false
	}
	b, ok := v.info().Uses[id].(*types.Builtin)
	return ok && b.Name() == "recover"
}

// implementsError reports whether t is a named or pointer type implementing
// the error interface.
func implementsError(t types.Type) bool {
	switch t.(type) {
	case *types.Named, *types.Pointer:
		return types.Implements(t, errorIface)
	}
	return false
}

// errorResults returns, for each result of call, whether it is an error.
func (v *visitor) errorResults(call *ast.CallExpr) []bool {
	t := v.info().TypeOf(call)
	if t == nil {
		return []bool{false}
	}
	if tuple, ok := t.(*types.Tuple); ok {
		out := make([]bool, tuple.Len())
		for i := range out {
			out[i] = implementsError(tuple.At(i).Type())
		}
		return out
	}
	return []bool{implementsError(t)}
}

// returnsError reports whether any result of call is an error.
func (v *visitor) returnsError(call *ast.CallExpr) bool {
	for _, isErr := range v.errorResults(call) {
		if isErr {
			return true
		}
	}
	return false
}

// calledIdent returns the identifier naming the callee for simple calls of
// the form f() or x.f().
func calledIdent(call *ast.CallExpr) *ast.Ident {
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		return fun
	case *ast.SelectorExpr:
		return fun.Sel
	}
	return nil
}

// unvendored strips a GOPATH-style vendor prefix from a package path.
func unvendored(path string) (string, bool) {
	i := strings.LastIndex(path, "/vendor/")
	if i < 0 {
		return path, false
	}
	return path[i+len("/vendor/"):], true
}

// isIgnored applies the -ignore / -ignorepkg rules to call.
func (v *visitor) isIgnored(call *ast.CallExpr) bool {
	id := calledIdent(call)
	if id == nil {
		return false
	}
	if re, ok := v.ignore[""]; ok && re.MatchString(id.Name) {
		return true
	}
	obj := v.info().Uses[id]
	if obj == nil || obj.Pkg() == nil {
		return false
	}
	path := obj.Pkg().Path()
	if re, ok := v.ignore[path]; ok {
		return re.MatchString(id.Name)
	}
	if short, ok := unvendored(path); ok {
		if re, ok := v.ignore[short]; ok {
			return re.MatchString(id.Name)
		}
	}
	return false
}

// calleeFunc returns the selector and function object for calls of the form
// x.f() where f resolves to a function or method.
func (v *visitor) calleeFunc(call *ast.CallExpr) (*ast.SelectorExpr, *types.Func, bool) {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return nil, nil, false
	}
	fn, ok := v.info().ObjectOf(sel.Sel).(*types.Func)
	if !ok {
		return nil, nil, false
	}
	return sel, fn, true
}

// qualifiedName returns the fully qualified name of the called function, or
// "" when it cannot be determined.
func (v *visitor) qualifiedName(call *ast.CallExpr) string {
	_, fn, ok := v.calleeFunc(call)
	if !ok {
		return ""
	}
	return fn.FullName()
}

// excludeNames returns all names under which call may be listed in the
// exclude set: the fully qualified function name, or, for methods reached
// through interfaces, one name per interface in the embedding chain.
func (v *visitor) excludeNames(call *ast.CallExpr) []string {
	sel, fn, ok := v.calleeFunc(call)
	if !ok {
		return nil
	}
	name := fn.FullName()
	selection, ok := v.info().Selections[sel]
	if !ok {
		return []string{name}
	}
	chain, ok := interfaceChain(selection)
	if !ok {
		return []string{name}
	}
	names := make([]string, len(chain))
	for i, t := range chain {
		names[i] = "(" + types.TypeString(t, nil) + ")." + fn.Name()
	}
	return names
}

// stdStream returns "os.Stdout" / "os.Stderr" when e refers to one of those
// package-level variables.
func (v *visitor) stdStream(e ast.Expr) (string, bool) {
	sel, ok := e.(*ast.SelectorExpr)
	if !ok {
		return "", false
	}
	obj, ok := v.info().ObjectOf(sel.Sel).(*types.Var)
	if !ok || obj.Pkg() == nil || obj.Pkg().Path() != "os" {
		return "", false
	}
	switch obj.Name() {
	case "Stdout", "Stderr":
		return "os." + obj.Name(), true
	}
	return "", false
}

// isExcluded reports whether call matches an entry of the exclude list.
func (v *visitor) isExcluded(call *ast.CallExpr) bool {
	names := v.excludeNames(call)
	if len(names) == 0 {
		return false
	}
	var argType, stream string
	if len(call.Args) > 0 {
		if t := v.info().TypeOf(call.Args[0]); t != nil {
			argType = types.TypeString(t, nil)
		}
		stream, _ = v.stdStream(call.Args[0])
	}
	for _, name := range names {
		if v.exclude[name] {
			return true
		}
		if argType != "" && v.exclude[name+"("+argType+")"] {
			return true
		}
		if stream != "" && v.exclude[name+"("+stream+")"] {
			return true
		}
	}
	return false
}

// report records a problem at pos; call may be nil for type assertions.
func (v *visitor) report(pos token.Pos, call *ast.CallExpr) {
	position := v.pkg.Fset.Position(pos)
	name := ""
	if call != nil {
		name = v.qualifiedName(call)
	}
	v.found = append(v.found, UncheckedError{
		Pos:      position,
		Line:     v.sourceLine(position),
		FuncName: name,
	})
}

// sourceLine returns the trimmed text of the line at position.
func (v *visitor) sourceLine(position token.Position) string {
	lines, ok := v.lines[position.Filename]
	if !ok {
		data, err := os.ReadFile(position.Filename)
		if err == nil {
			lines = strings.Split(string(data), "\n")
		}
		v.lines[position.Filename] = lines
	}
	if position.Line < 1 || position.Line > len(lines) {
		return ""
	}
	return strings.TrimSpace(lines[position.Line-1])
}
EOF
echo ok"}

