func TestIsGeneratedFile(t *testing.T) {
	cases := []struct {
		src  string
		want bool
	}{
		{"// Code generated by foo. DO NOT EDIT.\n\npackage p\n", true},
		{"package p\n\n// Code generated by foo. DO NOT EDIT.\n", true},
		{"/* Code generated by foo. DO NOT EDIT. */\n\npackage p\n", false},
		{"// Code generated DO NOT EDIT.\npackage p\n", false},
		{"// Code generated by foo. DO NOT EDIT\npackage p\n", false},
		{"// Code generated by foo. DO NOT EDIT. Really.\npackage p\n", false},
		{"//  Code generated by foo. DO NOT EDIT.\npackage p\n", false},
		{"package p\n", false},
	}
	for _, c := range cases {
		f, err := parser.ParseFile(token.NewFileSet(), "x.go", c.src, parser.ParseComments)
		if err != nil {
			t.Fatal(err)
		}
		if got := isGeneratedFile(f); got != c.want {
			t.Errorf("isGeneratedFile(%q) = %v, want %v", c.src, got, c.want)
		}
	}
}
