package main

import "testing"

func TestIgnoreFlagSet(t *testing.T) {
	f := ignoreFlag{}
	if err := f.Set(""); err != nil || len(f) != 0 {
		t.Fatalf("empty value should be a no-op, got %v %v", f, err)
	}
	if err := f.Set("os:Rem|Clo:se,strconv:Atoi,Foo"); err != nil {
		t.Fatal(err)
	}
	if f["os"].String() != "Rem|Clo:se" {
		t.Errorf("os regex = %q", f["os"].String())
	}
	if f["strconv"].String() != "Atoi" {
		t.Errorf("strconv regex = %q", f["strconv"].String())
	}
	if f[""].String() != "Foo" {
		t.Errorf("global regex = %q", f[""].String())
	}
	if err := f.Set("bad("); err == nil {
		t.Error("expected error for invalid regexp")
	}
}

func TestTagsFlagSet(t *testing.T) {
	var f tagsFlag
	for _, v := range []string{"a,b", "c d", "", "e,,f"} {
		if err := f.Set(v); err != nil {
			t.Fatal(err)
		}
	}
	want := "a b c d e f"
	if got := joinSpace(f); got != want {
		t.Errorf("tags = %q, want %q", got, want)
	}
}

func joinSpace(f tagsFlag) string {
	s := ""
	for i, t := range f {
		if i > 0 {
			s += " "
		}
		s += t
	}
	return s
}
